<template><div v-if="isAdmin" class="admin-shell"><aside><div class="brand">TOSHIO<span>餐厅管理</span></div><router-link to="/admin">后台首页</router-link><router-link to="/admin/orders">订单管理 <el-badge v-if="newCount" :value="newCount" /></router-link><router-link to="/admin/products">菜单管理</router-link><router-link to="/admin/store">店面管理</router-link><router-link :to="{path:'/guest',query:{storeId:activeStoreId}}" class="back">客人点餐 ↗</router-link></aside><main><header><span>店铺管理</span><div class="header-tools"><el-select v-if="stores.length" :model-value="activeStoreId" size="small" @change="selectStore"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select><span>🔔 新订单 {{newCount}}</span><el-button size="small" @click="logout">退出登录</el-button></div></header><section class="admin-content"><router-view/></section></main></div><router-view v-else/></template>
<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api} from './api';import {stores,activeStoreId,loadStores,selectStore} from './storeContext';const route=useRoute(),router=useRouter(),orders=ref<any[]>([]),isAdmin=computed(()=>route.path.startsWith('/admin')&&route.path!=='/admin/login'),newCount=computed(()=>orders.value.filter(o=>o.status==='new').length);let timer:number|undefined;async function poll(){if(!isAdmin.value)return;try{orders.value=(await api.get('/orders',{params:{storeId:activeStoreId.value}})).data.data}catch{}}async function logout(){try{await api.post('/auth/logout')}finally{orders.value=[];await router.push('/admin/login')}}onMounted(async()=>{try{await loadStores()}catch{}poll();timer=window.setInterval(poll,5000)});watch(activeStoreId,poll);onUnmounted(()=>clearInterval(timer));</script>
